  <Card padding="0">
    <Box padding="400">
      <InlineStack
        gap="300"
        align="space-between"
        blockAlign="center"
        wrap
      >
        <InlineStack gap="300" blockAlign="center" wrap>
          <Box minWidth="260px">
            <TextField
              label="Search"
              labelHidden
              value={searchQuery}
              onChange={handleSearchChange}
              placeholder="Search by email or zip code..."
