                      </BlockStack>
                    </IndexTable.Cell>
                    <IndexTable.Cell>
                      <Text as="span" fontWeight="bold">
                        {entry.zipCode}
                      </Text>
                    </IndexTable.Cell>
                    <IndexTable.Cell>
                      <Badge
