                      >
                        {entry.status.charAt(0).toUpperCase() + entry.status.slice(1)}
                      </Badge>
                    </IndexTable.Cell>
                    <IndexTable.Cell>
                      {formatDate(entry.createdAt)}
                    </IndexTable.Cell>
                    <IndexTable.Cell>
                      <InlineStack gap="200" wrap={false}>
                        {entry.status === "waiting" && (
                          <Tooltip content="Accept — adds ZIP to allowed list">
                            <Button
                              size="slim"
                              variant="tertiary"
                              tone="success"
