                        )}
                        <Tooltip content="Remove from waitlist">
                          <Button
                            size="slim"
                            variant="tertiary"
                            tone="critical"
                            onClick={() => handleDelete(entry.id)}
                            icon={DeleteIcon}
                            accessibilityLabel="Delete"
                          />
                        </Tooltip>
                      </InlineStack>
                    </IndexTable.Cell>
                  </IndexTable.Row>
                ))}
              </IndexTable>
            )}
          </Card>
        </Layout.Section>
      </Layout>
      </Box>

      {/* Add Entry Modal */}
      <Modal
        open={addModalOpen}
        onClose={() => {
          setAddModalOpen(false);
          setNewEmail("");
          setNewZipCode("");
          setNewNote("");
        }}
        title="Add Waitlist Entry"
        primaryAction={{ content: "Add to Waitlist", onAction: handleAdd }}
        secondaryActions={[
          {
