// ── Reusable position tile selector ─────────────────────────────────────────
const PositionTile = memo(function PositionTile({
  value,
  label,
  selected,
  disabled,
  onSelect,
  children,
}: {
  value: string;
  label: string;
  selected: boolean;
  disabled: boolean;
  onSelect: (v: string) => void;
  children: React.ReactNode;
}) {
  const handleClick = useCallback(() => {
    if (!disabled) onSelect(value);
  }, [disabled, onSelect, value]);

  return (
    <button
      type="button"
      aria-pressed={selected}
      onClick={handleClick}
      disabled={disabled}
      onKeyDown={(e) => {
        if ((e.key === "Enter" || e.key === " ") && !disabled) {
          e.preventDefault();
          onSelect(value);
        }
      }}
      style={{
        flex: 1,
        minWidth: 100,
        appearance: "none",
        WebkitAppearance: "none",
        border: "none",
        borderRadius: "var(--p-border-radius-200)",
        padding: "var(--p-space-300)",
        cursor: disabled ? "not-allowed" : "pointer",
        opacity: disabled ? 0.5 : 1,
        textAlign: "center",
        outline: "none",
        transition: "box-shadow 0.15s ease, background 0.15s ease",
        background: selected
          ? "var(--p-color-bg-surface-selected)"
          : "var(--p-color-bg-surface)",
        boxShadow: selected
          ? "0 0 0 2px var(--p-color-border-emphasis)"
          : "0 0 0 1px var(--p-color-border)",
        fontFamily: "inherit",
        color: "inherit",
        fontSize: "inherit",
      }}
    >
      <BlockStack gap="100" inlineAlign="center">
        {children}
        <Text as="p" variant="bodySm" fontWeight={selected ? "semibold" : "regular"}>
          {label}
        </Text>
      </BlockStack>
    </button>
  );
});

